"""Generate a clean .env.example from names only.

The generator takes a set of names and nothing else: it has no access
to any file's contents, so there is no code path by which a value
could reach the generated file. Lines are ``NAME=`` with an empty
right-hand side, grouped by the prefix before the first underscore.
"""
from __future__ import annotations

HEADER = (
    "# Generated by GhostEnv. Variable names only - this file never\n"
    "# contains values. Set real values in your local .env (not\n"
    "# committed) or in your host / CI environment.\n"
)


def group_names(names) -> list[tuple[str, list[str]]]:
    groups: dict[str, list[str]] = {}
    for name in sorted(set(names)):
        prefix = name.split("_", 1)[0] if "_" in name else ""
        groups.setdefault(prefix, []).append(name)
    ordered = sorted(groups.items(),
                     key=lambda kv: (kv[0] == "", kv[0]))
    return ordered


def render_example(names) -> str:
    lines = [HEADER.rstrip("\n"), ""]
    for prefix, group in group_names(names):
        if prefix:
            lines.append(f"# --- {prefix} ---")
        for name in group:
            lines.append(f"{name}=")
        lines.append("")
    return "\n".join(lines).rstrip("\n") + "\n"


def names_for_example(report: dict) -> list[str]:
    """Union of the three name sets in a doctor report, minus none.

    External (host-provided) names ARE included: the example file is
    where a new developer learns they must arrange them.
    """
    sets = report["sets"]
    names = (set(sets["used_in_code"]) | set(sets["defined_in_env"])
             | set(sets["documented_in_example"])
             | set(sets.get("external") or []))
    return sorted(names)
